<?php
namespace App\Controllers;
use PDO;use App\Core\{Auth,Response};use App\Services\AccountingExportService;
final class AccountingController{public function __construct(private PDO $db){}public function export():void{Auth::requirePermission('tax');$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$type=$_GET['type']??'csv';$wid=Auth::workspaceId();if($type==='zip'){$f=AccountingExportService::package($this->db,$wid,$from,$to,dirname(__DIR__,2));header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="'.basename($f).'"');readfile($f);exit;}if($type==='pohoda'){$x=AccountingExportService::pohodaXml($this->db,$wid,$from,$to);header('Content-Type: application/xml; charset=UTF-8');header('Content-Disposition: attachment; filename="pohoda_'.$from.'_'.$to.'.xml"');echo $x;exit;}$csv=AccountingExportService::csv($this->db,$wid,$from,$to);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="byznio_'.$from.'_'.$to.'.csv"');echo "\xEF\xBB\xBF".$csv;exit;}}
